jQuery(document).ready(function(e){const t=new URLSearchParams(window.location.search).get("message");if(t&&"function"==typeof window.yaliToast&&"undefined"!=typeof camRulesListI18n){switch(t){case"1":window.yaliToast(camRulesListI18n.addSuccess,"success");break;case"2":window.yaliToast(camRulesListI18n.saveError,"error");break;case"3":window.yaliToast(camRulesListI18n.updateSuccess,"success");break;case"4":window.yaliToast(camRulesListI18n.deleteSuccess,"success");break;case"5":window.yaliToast(camRulesListI18n.deleteError,"error")}const e=window.location.protocol+"//"+window.location.host+window.location.pathname+"?page=yali-ai-writer-rules";window.history.replaceState({path:e},"",e)}document.querySelectorAll('button:disabled[title*="编辑"]').forEach(e=>{e.style.cursor="not-allowed",e.addEventListener("click",function(e){e.preventDefault(),"undefined"!=typeof camRulesListI18n&&alert(camRulesListI18n.ruleInUseEdit)})});document.querySelectorAll('button:disabled[title*="删除"]').forEach(e=>{e.style.cursor="not-allowed",e.addEventListener("click",function(e){e.preventDefault(),"undefined"!=typeof camRulesListI18n&&alert(camRulesListI18n.ruleInUseDelete)})})});